insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"the_alphabet_adventure_q01_finish","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q01_start","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q02_finish","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q02_start","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q03_finish","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q03_start","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q04_finish","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q04_start","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q05_finish","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q05_start","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q06_finish","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q06_start","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q07_finish","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}},{"key":"the_alphabet_adventure_q07_start","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\the_alphabet_adventure.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"the_alphabet_adventure_q01_finish","locale":"he","line_order":0,"content":"תפוח! עכשיו אני נזכר שלקחתי תפוח כשיצאתי מהבקתה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_finish","locale":"he","line_order":1,"content":"תרגלת את שתי הצורות של האות שלנו. ברמז הבא מצויר התיק שלי. אולי הוא יזכיר לי מה קרה אחר כך.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":0,"content":"אני אורן. הערב אספר סיפור בחגיגת הממלכה, אבל הספר שלי נעול בתיבה ושכחתי איפה המפתח.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":1,"content":"כתבתי לעצמי רמזים. חלק מהאותיות נמחקו, וברמז הראשון מצויר תפוח. בוא נפענח אותו יחד.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":2,"content":"נתחיל באות A, שנקראת איי. A היא הצורה הגדולה, ו-a היא הצורה הקטנה. זאת אותה אות.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":3,"content":"A היא אות ניקוד באנגלית. כאן זאת אות שכותבים בשורה, והיא עוזרת לייצג צליל. בעברית סימני הניקוד הם סימנים סביב האותיות.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":4,"content":"A היא מיוחדת ויש לה כמה צלילים. Apple פירושו תפוח. Acorn פירושו בלוט. שתי המילים מתחילות באותה אות, אבל הצליל הראשון שונה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":5,"content":"בתחילת acorn הצליל דומה לשם האות איי. בתחילת apple נשמע צליל אחר. עכשיו נקשיב להקלטה של apple, ובשיעורי הבית נחזור גם ל-acorn.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":6,"content":"שם האות והצליל שלה בתוך מילה אינם תמיד אותו הדבר. אין צורך לקרוא או לכתוב את כל המילים האלה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":7,"content":"בשולחן הלימוד שבפארק תצייר A ו-a. במכרה תאסוף אותן, ואחר כך תקשיב למילת הרמז ותבחר את האות שלה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":8,"content":"לסיום תחתוך a שלוש פעמים. הסימנים האחרים הם רק אפשרויות להבחנה; היום לומדים את A.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_finish","locale":"he","line_order":0,"content":"נכון, לקחתי את התיק. התפוח היה בפנים, אבל שמעתי ממנו רחש מוזר.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_finish","locale":"he","line_order":1,"content":"ברמז הבא מצויר מי שהתחבא בו. לא ידעתי שיש לי אורח בתיק!","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_start","locale":"he","line_order":0,"content":"ברמז הבא מצויר התיק שלי. הוא היה כבד מהרגיל, וגם השמיע רחש. מעניין מה הסתתר בו.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_start","locale":"he","line_order":1,"content":"Bag פירושו תיק. האות הראשונה היא B, שנקראת בי. B היא הצורה הגדולה, ו-b הקטנה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_start","locale":"he","line_order":2,"content":"בהקלטה תקשיב לתחילת bag, המילה האנגלית לתיק. הצליל הראשון שייך ל-B. כדי לחבר צלילים, נשתמש בצליל הזה ולא בשם בי.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_start","locale":"he","line_order":3,"content":"אחרי B נחבר A עם הצליל שלה בהקלטה של apple. נקבל צירוף שנכתוב בקירוב בא בעברית. זה צירוף לתרגול, ולא מילה באנגלית.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_start","locale":"he","line_order":4,"content":"העברית עוזרת לזכור את הצירוף בקירוב. את הצליל האנגלי של A מכירים דרך ההקלטה של apple.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_start","locale":"he","line_order":5,"content":"בשולחן שבפארק תצייר B ו-b, תאסוף את שתי הצורות ותאזין לרמז של התיק.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_start","locale":"he","line_order":6,"content":"אחר כך תחבר שתי אותיות ותשלים רק את תחילת המילה. הסוף כבר כתוב, ואין צורך לקרוא את כולו לבד.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_finish","locale":"he","line_order":0,"content":"החתול שלי! הוא התחבא בתיק, וכשפתחתי אותו הוא קפץ החוצה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_finish","locale":"he","line_order":1,"content":"החזקתי את המפתח באותו רגע. הרמז האחרון הוא הכתובת שעל הכרית שקיבלתי מהבת שלי.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_start","locale":"he","line_order":0,"content":"ברמז מצויר חתול. עכשיו אני מתחיל להבין מאיפה בא הרחש.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_start","locale":"he","line_order":1,"content":"Cat פירושו חתול. האות החדשה היא C, שנקראת סי. C גדולה ו-c קטנה הן אותה אות.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_start","locale":"he","line_order":2,"content":"בתחילת cat, המילה האנגלית לחתול, C נשמעת כמו הצליל בתחילת המילה קרן בעברית. תקשיב גם לדוגמה באנגלית.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_start","locale":"he","line_order":3,"content":"ל-C יש גם צלילים אחרים. היום נשתמש בצליל שלה בדוגמה של החתול.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_start","locale":"he","line_order":4,"content":"נחבר את הצליל הזה ל-A עם הצליל שלה בהקלטה של apple. נכתוב את הצירוף בקירוב קא בעברית. זה תרגול של שני צלילים, ולא מילה באנגלית.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_start","locale":"he","line_order":5,"content":"בשולחן שבפארק תצייר C ו-c, תאסוף אותן ותקשיב למילת הרמז.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_start","locale":"he","line_order":6,"content":"אחר כך תחבר שתי אותיות ותשלים רק את האות הראשונה במילה חתול. הסוף כבר כתוב, כי עוד לא למדנו את כולו.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":0,"content":"Dad, אבא! הבת שלי רקמה את המילה על הכרית ליד החלון.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":1,"content":"כשהחתול קפץ, הנחתי שם את המפתח והרמתי אותו בשתי הידיים. עכשיו נזכרתי איפה לחפש.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":2,"content":"מצאתי את המפתח ופתחתי את התיבה. הספר בפנים, ובחגיגה אספר איך עזרת לי.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":3,"content":"אני נותן לך 5 מטבעות על העזרה. אותיות הן כמו מפתחות קטנים לסיפורים.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":4,"content":"מאיה הכינה לך עוד שלושה תרגולים קצרים לשיעורי הבית.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_start","locale":"he","line_order":0,"content":"ברמז האחרון מצוירת הכרית שהבת שלי נתנה לי. היא רקמה עליה הקדשה, אבל חלק מהכתב ברמז נמחק.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_start","locale":"he","line_order":1,"content":"האות החדשה היא D, שנקראת די. D היא הצורה הגדולה, ו-d הקטנה. בתחילת dog, שפירושה כלב, שומעים את הצליל שלה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_start","locale":"he","line_order":2,"content":"השם די שונה מהצליל בתחילת dog. הקשב להקלטה כדי להכיר את הצליל.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_start","locale":"he","line_order":3,"content":"ל-b יש קו גבוה משמאל לבטן, ול-d יש קו גבוה מימין לבטן. בדוק את הצורות באנגלית לפני שתבחר.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_start","locale":"he","line_order":4,"content":"נחבר D ואחריה A עם הצליל שלה בהקלטה של apple. נכתוב את הצירוף בקירוב דא בעברית. זה תרגול, ולא מילה באנגלית.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_start","locale":"he","line_order":5,"content":"עכשיו נוסיף עוד D בסוף: dad. Dad פירושו אבא. זאת מילה אמיתית שכל האותיות שלה כבר מוכרות לך.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_start","locale":"he","line_order":6,"content":"אם נחליף את האות הראשונה ב-B נקבל bad. Bad פירושו רע. שינוי האות הראשונה משנה גם את הצליל ואת המשמעות.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_start","locale":"he","line_order":7,"content":"בשולחן שבפארק תצייר D ו-d, תאסוף אותן, תחבר את הצירוף ותאזין למילים.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_start","locale":"he","line_order":8,"content":"לסיום תחתוך את האותיות של אבא לפי הסדר. צריך d בהתחלה וגם d בסוף.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q05_finish","locale":"he","line_order":0,"content":"כל הכבוד. הבחנת בין צורות גדולות וקטנות וחזרת על שתי האותיות שקל לבלבל.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q05_finish","locale":"he","line_order":1,"content":"בתרגול הבא תחבר אותיות לצירופים קצרים.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q05_start","locale":"he","line_order":0,"content":"הספר של אורן מוכן לחגיגה. אני מאיה, ולפני השיעור הבא נחזור על ארבע האותיות שלמדת.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q05_start","locale":"he","line_order":1,"content":"במכרה הראשון תאסוף רק אותיות גדולות. במכרה השני תאסוף רק אותיות קטנות. שים לב לצורה, לא לגודל הציור על המסך.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q05_start","locale":"he","line_order":2,"content":"אחר כך תצייר b ו-d. ב-b הקו הגבוה משמאל לבטן, וב-d הוא מימין.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q05_start","locale":"he","line_order":3,"content":"התרגולים מחכים לך בשולחן הלימוד שבפארק.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q06_finish","locale":"he","line_order":0,"content":"חיברת צירופים בשתי דרכים וחזרת על אות הניקוד A דרך דוגמה נוספת.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q06_finish","locale":"he","line_order":1,"content":"ב-apple וב-acorn זו אותה אות עם צלילים שונים. בתרגול האחרון נרכיב שתי מילים אמיתיות שכבר למדת.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q06_start","locale":"he","line_order":0,"content":"אורן רוצה להציג בחגיגה את הרמזים שפתרת. היום נחזור אליהם בכמה דרכים.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q06_start","locale":"he","line_order":1,"content":"תרכיב את הצירוף קא, ואחר כך תחתוך את האותיות של בא. אלו צירופים לתרגול, ולא מילים באנגלית.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q06_start","locale":"he","line_order":2,"content":"בכל צירוף נשמור על הצליל של A בהקלטה של apple. הכתיבה בעברית מזכירה את סדר הצלילים בקירוב.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q06_start","locale":"he","line_order":3,"content":"בסוף תקשיב למילה acorn, שפירושה בלוט. היא מתחילה ב-A עם צליל שדומה לשם האות איי.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q06_start","locale":"he","line_order":4,"content":"זו אותה אות ניקוד של תפוח, אבל הצליל הראשון שונה. בחר רק את האות של הצליל הראשון, בלי לכתוב את המילה כולה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q07_finish","locale":"he","line_order":0,"content":"סיימת את ההרפתקה ואת שלושת תרגולי הבית. הכרת את A, B, C ו-D וחיברת צלילים לצירופים ולמילים קטנות.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q07_finish","locale":"he","line_order":1,"content":"אני נותנת לך 5 מטבעות על השלמת תרגולי הבית. עכשיו יש לך בסיס להמשך, ובשיעור הבא נוסיף אות חדשה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q07_start","locale":"he","line_order":0,"content":"לסיום נחזור על שתי מילים אמיתיות. Dad פירושו אבא, ו-bad פירושו רע.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q07_start","locale":"he","line_order":1,"content":"הסוף שלהן זהה, והאות הראשונה משנה את הצליל ואת המשמעות.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q07_start","locale":"he","line_order":2,"content":"בשולחן שבפארק תרכיב מילה לפי המשמעות, תקשיב למילה נוספת ותסיים בחיתוך אותיות לפי הסדר.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q07_start","locale":"he","line_order":3,"content":"כשמעשה הוא רע, אפשר לתקן אותו. טעות בתרגול היא חלק מהלמידה.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
